def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path.strip():
        raise ValueError("Invalid path")
    try:
        return [(d, {k: int(v) for k, v in dstat(d).items()}) for d in path.split(delimiter)]
    except FileNotFoundError:
        raise FileNotfoundError(f"FileNotFoundError: '{path}'")

def dstat(dir):
    total = sum(os.path.getsize(p) for p in os.listdir(dir))
    used = sum(os.path.getsize(p) for p in filter(lambda p: os.path.isfile(os.path.join(dir, p)), os.listdir(dir)))
    free = total - used
    return {"total": total, "used": used, "free": free}
